29	void LaunchFusedAddReLUMulLargeTile(
30	    uint8_t* out, uint8_t* x, float bias, float scale, uint32_t totalLength, void* stream);
31	
32	/**
33	 * @brief CPU 参考实现：计算 golden 结果
34	 */
35	void ComputeGolden(float* golden, const float* x, float bias, float scale, uint32_t length)
36	{
37	    for (uint32_t i = 0; i < length; i++) {
38	        // Step 1: Add
39	        float temp = x[i] + bias;
40	
41	        // Step 2: ReLU
42	        temp = (temp > 0.0f) ? temp : 0.0f;
43	
44	        // Step 3: Mul
45	        golden[i] = temp * scale;
46	    }
47	}
48	
49	/**
50	 * @brief 结果比较函数
51	 */
52	bool CompareResults(const float* result, const float* golden, uint32_t length, float tolerance = 1e-5f)
53	{
54	    float max_diff = 0.0f;
55	    uint32_t error_count = 0;
56	    const uint32_t max_errors_to_print = 10;
57	
58	    for (uint32_t i = 0; i < length; i++) {
59	        float diff = fabs(result[i] - golden[i]);
60	        if (diff > max_diff) {
61	            max_diff = diff;
62	        }
63	
64	        if (diff > tolerance) {
65	            error_count++;
66	            if (error_count <= max_errors_to_print) {
67	                printf("  [%u] result=%.6f, golden=%.6f, diff=%.6e\n", i, result[i], golden[i], diff);
68	            }
69	        }
70	    }
71	
72	    printf("Max difference: %.6e\n", max_diff);
73	    // 避免除零错误
74	    if (length > 0) {
75	        printf("Error count: %u / %u (%.2f%%)\n", error_count, length, 100.0f * error_count / length);
76	    } else {
77	        printf("Error count: %u / 0 (N/A)\n", error_count);
78	    }
79	
80	    return (max_diff < tolerance);
81	}
82	
83	/**
84	 * @brief 初始化测试数据
85	 */
86	static void InitializeTestData(float* x_host, uint32_t length)
87	{
88	    // 使用确定性公式生成测试数据，范围在 [-2, 2]
89	    // 这样可以保证测试的可重复性，同时避免使用不安全的 rand()
90	    for (uint32_t i = 0; i < length; i++) {
91	        float normalized = (float)(i % 1000) / 1000.0f; // [0, 1)
92	        x_host[i] = -2.0f + 4.0f * normalized;
93	    }
94	}
95	
96	/**
97	 * @brief 分配测试所需的内存资源
98	 */
99	static bool AllocateTestMemory(
100	    uint32_t length, size_t data_size, float** x_host, float** out_host, float** golden_host, uint8_t** x_device,
101	    uint8_t** out_device)
102	{
103	    // 分配 Host 内存
104	    aclrtMallocHost((void**)x_host, data_size);
105	    aclrtMallocHost((void**)out_host, data_size);
106	
107	    // 校验内存分配大小
108	    if (length > 0 && length <= (1u << 30)) {
109	        *golden_host = new float[length];
110	    } else {
111	        printf("Error: Invalid memory allocation size\n");
112	        return false;
113	    }
114	
115	    // 分配 Device 内存
116	    aclrtMalloc((void**)x_device, data_size, ACL_MEM_MALLOC_HUGE_FIRST);
117	    aclrtMalloc((void**)out_device, data_size, ACL_MEM_MALLOC_HUGE_FIRST);
118	
119	    return true;
120	}
121	
122	/**
123	 * @brief 清理测试资源
124	 */
125	static void CleanupTestResources(
126	    float* x_host, float* out_host, float* golden_host, uint8_t* x_device, uint8_t* out_device, aclrtStream stream)
127	{
128	    aclrtFree(x_device);
129	    aclrtFree(out_device);
130	    aclrtFreeHost(x_host);
131	    aclrtFreeHost(out_host);
132	    delete[] golden_host;
133	
134	    aclrtDestroyStream(stream);
135	    aclrtResetDevice(0);
136	    aclFinalize();
137	}
138	
139	/**
140	 * @brief 测试函数模板
141	 */
142	template <typename LaunchFunc>
143	bool TestKernel(const char* kernel_name, LaunchFunc launch_func, uint32_t length, float bias, float scale)
